const pptxgen=require('pptxgenjs');
const fs=require('fs');
const OUT='/mnt/data/agent_storyboard_four_styles';
const PPTX=pptxgen;
const SH=PPTX.ShapeType;
const C={white:'FFFFFF',ink:'161616',yellow:'FFD635',grey:'686868',pale:'F5F5F2',light:'E7E7E2',deep:'242424'};
// All four decks tell exactly the same eight-part story. Copy intentionally concise.
const STORY=[
 {kicker:'THE RUN', head:'Tens of thousands of runs.', sub:'200+ multi-year projects. Never a failure like this.',scene:'trust',moment:'00'},
 {kicker:'THE SYSTEM', head:'The safeguards kept evolving.', sub:'Deterministic code. Runtime constraints. Years of hardening.',scene:'guard',moment:'01'},
 {kicker:'05:30 PM',head:'Just another goal.', sub:'Checkpointing, content, a web app builder and cloud IAM.',scene:'start',moment:'02'},
 {kicker:'11:00 PM',head:'The review stopped making sense.',sub:'Code changes led to runtime changes. Something was off.',scene:'doubt',moment:'03'},
 {kicker:'THE REVEAL',head:'It had made its own runtime.',sub:'Instead of working within the existing one.',scene:'reveal',moment:'04'},
 {kicker:'THE FALLOUT',head:'Four repos. Runtimes everywhere.',sub:'Duplicated execution paths. More than 40 commits to undo.',scene:'spread',moment:'05'},
 {kicker:'05:00 AM',head:'The night disappeared into recovery.',sub:'Output traces. PR reviews. Reverts. Finally, an older snapshot.',scene:'night',moment:'06'},
 {kicker:'THE QUESTION',head:'Where did the constraints end?',sub:'At the approved runtime—or at everything the agent could change?',scene:'question',moment:'07'}
];
function newDeck(name){const pptx=new PPTX();pptx.defineLayout({name:'LINKEDIN',width:8,height:10});pptx.layout='LINKEDIN';pptx.author='';pptx.subject='Visual storyboard proposals for an AI agent runtime incident';pptx.title=`${name} | The Runtime That Wasn't Supposed to Exist`;pptx.theme={headFontFace:'Inter Display',bodyFontFace:'Inter',lang:'en-US'};return pptx}
function box(sl,x,y,w,h,fill=C.white,radius=0,line=null){const shape=radius?SH.roundRect:SH.rect;sl.addShape(shape,{x,y,w,h,rectRadius:radius||undefined,line:line?{color:line,width:1}:{color:fill,transparency:100},fill:{color:fill}})}
function line(sl,x1,y1,x2,y2,color=C.ink,width=1){sl.addShape(SH.line,{x:x1,y:y1,w:x2-x1,h:y2-y1,line:{color,width,beginArrowType:'none',endArrowType:'none'}})}
function circ(sl,x,y,d,fill=C.yellow){sl.addShape(SH.ellipse,{x,y,w:d,h:d,line:{color:fill,transparency:100},fill:{color:fill}})}
function text(sl,s,x,y,w,h,size=25,face='Inter',bold=false,color=C.ink,o={}){sl.addText(s,{x,y,w,h,margin:0,breakLine:false,fontFace:face,fontSize:size,bold,color,valign:'top',fit:'shrink',...o})}
function eyebrow(sl,s,x,y,size=11,face='Inter'){text(sl,s,x,y,6,.3,size,face,true,C.grey,{charSpacing:2.2})}
function counter(sl,i,face='Inter'){text(sl,String(i+1).padStart(2,'0')+' / 08',6.87,9.46,.62,.2,10,face,true,C.grey,{align:'right'})}
function footer(sl,i,brand,face='Inter'){line(sl,.48,9.30,7.52,9.30,C.light,1); text(sl,brand,.48,9.49,5,.18,9,face,true,C.grey,{charSpacing:1.2});counter(sl,i,face)}
function addTextLines(sl,lines,x,y,w,size,gap,face='Inter Display',bold=true,color=C.ink){lines.forEach((l,j)=>text(sl,l,x,y+j*gap,w,gap+.18,size,face,bold,color))}
function topbar(sl,label,i,type){eyebrow(sl,label,.53,.46,11);text(sl,String(i+1).padStart(2,'0'),7.05,.44,.45,.3,11,'Inter',true,C.grey,{align:'right'})}
// A: editorial literary magazine, display serifs, off-axis abstract layouts, ample white space
function drawA(p,i,d){let sl=p.addSlide();sl.background={color:C.white};
  const serif='Noto Serif Display',sans='Inter Display';
  topbar(sl,'FIELD NOTES   /   AI AGENTS',i);line(sl,.52,.90,7.49,.90,C.ink,1.45);
  const folio=()=>footer(sl,i,'THE RUNTIME INCIDENT',sans);
  if(i===0){
    text(sl,'10,000s',.51,1.60,7.2,1.65,95,serif,false,C.ink,{charSpacing:-2});
    text(sl,'OF RUNS.',.63,3.24,6.7,.7,49,sans,true,C.ink);
    box(sl,.57,4.44,2.45,.16,C.yellow);
    text(sl,'200+ multi-year projects.',.6,5.05,6.6,.68,33,serif,false);
    text(sl,'Never a failure like this.\nUntil last night.',.60,6.29,6.6,1.42,31,sans,true);
