    line(sl,.62,2.24,7.31,2.24,C.ink,1.2);
    text(sl,'Hours of tracing.\nPR reviews. Reverts.',.58,2.95,6.9,2.45,48,serif,false);
    text(sl,'05:00',.60,6.37,6.8,1.30,88,serif,false);
    text(sl,'AM. Finally back to a clean snapshot.',.60,8.04,6.85,.52,21,sans,false);
    circ(sl,6.75,8.50,.38,C.yellow);
  } else {
    text(sl,'Where did\nthe constraints\nend?',.55,1.43,6.94,3.45,59,serif,false);
    box(sl,.58,5.33,5.74,.14,C.yellow);
